260	    @Override
261	    @Transactional
262	    public void createOwner(Owner owner, boolean sharesHousehold) throws DataAccessException {
263	        rejectWhenDailyLimitReached(owner);
264	        rejectWhenCityAtCapacity(owner);
265	        List<Owner> householdMembers = assignHousehold(owner, sharesHousehold);
266	        rejectWhenDuplicateIdentity(owner);
267	        assignPossibleDuplicate(owner);
268	        owner.setHouseholdMemberCount(householdMembers.size() + 1);
269	        if (owner.getCustomerCode() == null) {
270	            owner.setCustomerCode(deriveCustomerCode(owner));
271	        }
272	        if (owner.getNamesakeCount() == null) {
273	            owner.setNamesakeCount(countNamesakes(owner));
274	        }
275	        owner.setBulkSignupWarning(exceedsBulkSignupThreshold(owner));
276	        ownerRepository.save(owner);
277	    }
278	
279	    /** Number of owners created on a single day beyond which the bulk-signup warning is raised. */
280	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80L;
281	
282	    /**
283	     * Whether more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created
284	     * today (compared by {@code registrationDate}), evaluated before this owner is persisted so it
285	     * reflects the owners present at creation time. The new owner's registration date, defaulted to
286	     * today by the controller, determines which day is counted — the same accumulation path as the
287	     * daily-limit rule.
288	     */
289	    private boolean exceedsBulkSignupThreshold(Owner owner) {
290	        LocalDate day = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
291	        return countOwnersRegisteredOn(day) > BULK_SIGNUP_WARNING_THRESHOLD;
292	    }
293	
294	    /**
295	     * Count the existing owners that already share this owner's first name and last name,
296	     * compared case-insensitively (with surrounding/collapsed whitespace ignored). Evaluated
297	     * before the owner is persisted, so it reflects the owners present at creation time.
298	     */
299	    private int countNamesakes(Owner owner) {
300	        String firstName = IdentityNormalizer.normalize(owner.getFirstName());
301	        String lastName = IdentityNormalizer.normalize(owner.getLastName());
302	        return (int) ownerRepository.findAll().stream()
303	            .filter(existing -> firstName.equals(IdentityNormalizer.normalize(existing.getFirstName()))
304	                && lastName.equals(IdentityNormalizer.normalize(existing.getLastName())))
305	            .count();
306	    }
307	
308	    /**
309	     * Reconcile the owner's household and return its existing members. Owners are in the same
310	     * household when their last name and address match (compared case-insensitively with collapsed
311	     * whitespace). When another owner already lives there and {@code sharesHousehold} is set, the
312	     * new owner and every existing member are given the same stable shared {@code householdId} so
313	     * they form one household; without the opt-in the owner is treated as living alone (no shared
314	     * identifier). Duplicate detection no longer happens here: it is consolidated into the derived
315	     * {@code identityKey} (see {@link #rejectWhenDuplicateIdentity(Owner)}). The returned list is the
316	     * existing members that make up this owner's household (empty when the owner lives alone), so
317	     * callers can derive the household size after this create.
318	     */
319	    private List<Owner> assignHousehold(Owner owner, boolean sharesHousehold) {
320	        if (!sharesHousehold) {
321	            return List.of();
322	        }
323	        String lastName = IdentityNormalizer.normalize(owner.getLastName());
324	        String address = AddressNormalizer.canonical(owner.getAddress());
325	        List<Owner> householdMembers = ownerRepository.findAll().stream()
326	            .filter(existing -> lastName.equals(IdentityNormalizer.normalize(existing.getLastName()))
327	                && address.equals(AddressNormalizer.canonical(existing.getAddress())))
328	            .toList();
329	        if (householdMembers.isEmpty()) {
330	            return householdMembers;
331	        }
332	        String householdId = householdMembers.stream()
333	            .map(Owner::getHouseholdId)
334	            .filter(Objects::nonNull)
335	            .findFirst()
336	            .orElseGet(() -> deriveHouseholdId(lastName, address));
337	        owner.setHouseholdId(householdId);
338	        for (Owner member : householdMembers) {
339	            if (!householdId.equals(member.getHouseholdId())) {
340	                member.setHouseholdId(householdId);
341	                ownerRepository.save(member);
342	            }
343	        }
344	        return householdMembers;
345	    }
346	
347	    /**
348	     * Derive a stable, shared household identifier from the normalized last name and address, so
349	     * every owner in the same household deterministically maps to the same value.
350	     */
351	    private static String deriveHouseholdId(String normalizedLastName, String normalizedAddress) {
352	        String key = normalizedLastName + "\n" + normalizedAddress;
353	        return UUID.nameUUIDFromBytes(key.getBytes(StandardCharsets.UTF_8)).toString();
354	    }
355	
356	    /**
357	     * Reject the create when the owner's derived {@code identityKey} exactly matches that of an
358	     * existing owner. The key —
359	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId} — is the single value
360	     * into which the former separate telephone, e-mail and household duplicate checks are
361	     * consolidated: only an exact whole-key match is a duplicate, so two members of the same
362	     * household with different telephones (hence different keys) are both allowed. Evaluated after
363	     * the household has been reconciled (so the {@code householdId} segment is settled) and before
364	     * the owner is persisted, so it reflects the owners present at creation time.
365	     */
366	    private void rejectWhenDuplicateIdentity(Owner owner) {
367	        String identityKey = IdentityKeyNormalizer.derive(owner);
368	        boolean duplicate = ownerRepository.findAll().stream()
369	            .anyMatch(existing -> identityKey.equals(IdentityKeyNormalizer.derive(existing)));
370	        if (duplicate) {
371	            throw new DuplicateIdentityException(
372	                "an owner with identity key " + identityKey + " already exists");
373	        }
374	    }
375	
376	    /**
377	     * Flag the new owner as a possible (soft) duplicate when it is not a hard duplicate but shares
378	     * an existing owner's last name and postcode (compared case-insensitively with collapsed
379	     * whitespace) while carrying a different telephone. When such an owner exists the new owner's
380	     * {@code possibleDuplicate} is set to {@code true} and {@code possibleDuplicateOf} to the
381	     * matching owner's id (the lowest id when several match); otherwise {@code possibleDuplicate}
382	     * is {@code false} and {@code possibleDuplicateOf} is left unset. Evaluated after the
383	     * hard-duplicate check and before the owner is persisted, so it reflects the owners present at
384	     * creation time.
385	     */
386	    private void assignPossibleDuplicate(Owner owner) {
387	        String lastName = IdentityNormalizer.normalize(owner.getLastName());
388	        String postcode = IdentityNormalizer.normalize(owner.getPostcode());
389	        String telephone = TelephoneNormalizer.toComparable(owner.getTelephone());
390	        Owner match = ownerRepository.findAll().stream()
391	            .filter(existing -> lastName.equals(IdentityNormalizer.normalize(existing.getLastName()))
392	                && postcode.equals(IdentityNormalizer.normalize(existing.getPostcode()))
393	                && !telephone.equals(TelephoneNormalizer.toComparable(existing.getTelephone())))
394	            .min(Comparator.comparingInt(existing -> existing.getId() == null ? Integer.MAX_VALUE : existing.getId()))
395	            .orElse(null);
396	        if (match != null) {
397	            owner.setPossibleDuplicate(true);
398	            owner.setPossibleDuplicateOf(match.getId());
399	        }
400	        else {
401	            owner.setPossibleDuplicate(false);
402	            owner.setPossibleDuplicateOf(null);
403	        }
404	    }
405	
406	    /** Maximum number of owners that may be created on any single day (by registration date). */
407	    private static final long DAILY_OWNER_LIMIT = 100L;
408	
409	    /**
410	     * Reject the create when {@value #DAILY_OWNER_LIMIT} or more owners have already been created
411	     * today (compared by {@code registrationDate}). Evaluated before the owner is persisted, so it
412	     * reflects the owners present at creation time. The new owner's own registration date, defaulted
413	     * to today by the controller, determines which day the limit is checked against.
414	     */
415	    private void rejectWhenDailyLimitReached(Owner owner) {
416	        LocalDate day = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
417	        if (countOwnersRegisteredOn(day) >= DAILY_OWNER_LIMIT) {
418	            throw new DailyOwnerLimitExceededException(
419	                DAILY_OWNER_LIMIT + " or more owners have already been created on " + day);
420	        }
421	    }
422	
423	    /**
424	     * Count the existing owners whose {@code registrationDate} equals the given day. Evaluated
425	     * before the owner is persisted, so it reflects the owners present at creation time.
426	     */
427	    private long countOwnersRegisteredOn(LocalDate day) {
428	        return ownerRepository.findAll().stream()
429	            .filter(existing -> day.equals(existing.getRegistrationDate()))
430	            .count();
431	    }
432	
433	    /** Maximum number of owners allowed to live in any single city. */
434	    private static final long CITY_CAPACITY = 50L;
435	
436	    /**
437	     * Reject the create when the owner's city already contains {@value #CITY_CAPACITY} or more
438	     * owners (compared case-insensitively with collapsed whitespace). Evaluated before the owner
439	     * is persisted, so it reflects the owners present at creation time.
440	     */
441	    private void rejectWhenCityAtCapacity(Owner owner) {
442	        if (countOwnersInCity(owner) >= CITY_CAPACITY) {
443	            throw new CityCapacityExceededException(
444	                "city " + owner.getCity() + " already contains " + CITY_CAPACITY + " or more owners");
445	        }
446	    }
447	
448	    /**
449	     * Count the existing owners that already live in this owner's city, compared
450	     * case-insensitively (with surrounding/collapsed whitespace ignored). Evaluated before the
451	     * owner is persisted, so it reflects the owners present at creation time.
452	     */
453	    private long countOwnersInCity(Owner owner) {
454	        String city = IdentityNormalizer.normalize(owner.getCity());
455	        return ownerRepository.findAll().stream()
456	            .filter(existing -> city.equals(IdentityNormalizer.normalize(existing.getCity())))
457	            .count();
458	    }
459	
460	    /** Region-to-inclusive 4-digit postcode range {@code {low, high}}. */
461	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
462	        "NSW", new int[] {2000, 2099},
463	        "VIC", new int[] {3000, 3099},
464	        "QLD", new int[] {4000, 4099});
465	
466	    /** Region code used when the postcode maps to no known region (or is absent). */
467	    private static final String UNKNOWN_REGION = "UNKNOWN";
468	
469	    /**
470	     * Builds the customer code {@code '<REGION>-<HASH8>'}: the region code derived from the
471	     * owner's postcode, a hyphen, and the first eight upper-case hexadecimal characters of the
472	     * SHA-256 digest over the owner's normalized (E.164) telephone concatenated with the last
473	     * name. No sequence number is used; the identity is fully derived from the region and hash.
474	     */
475	    private String deriveCustomerCode(Owner owner) {
476	        String region = regionForPostcode(owner.getPostcode());
477	        String telephone = TelephoneNormalizer.toComparable(owner.getTelephone());
478	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
479	        return region + "-" + sha256Hex8(telephone + lastName);
480	    }
481	
482	    /**
483	     * Returns the region code whose inclusive postcode range contains {@code postcode}
484	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), or
485	     * {@code "UNKNOWN"} when the postcode is absent, not a 4-digit value, or in no known range.
486	     */
487	    private static String regionForPostcode(String postcode) {
488	        if (postcode == null || !postcode.matches("\\d{4}")) {
489	            return UNKNOWN_REGION;
490	        }
491	        int value = Integer.parseInt(postcode);
492	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
493	            int[] range = entry.getValue();
494	            if (value >= range[0] && value <= range[1]) {
495	                return entry.getKey();
496	            }
497	        }
498	        return UNKNOWN_REGION;
499	    }
500	
501	    /**
502	     * Returns the first eight upper-case hexadecimal characters (the first four bytes) of the
503	     * SHA-256 digest of the UTF-8 bytes of {@code value}.
504	     */
505	    private static String sha256Hex8(String value) {
506	        try {
507	            byte[] digest = MessageDigest.getInstance("SHA-256")
508	                .digest(value.getBytes(StandardCharsets.UTF_8));
509	            StringBuilder sb = new StringBuilder(8);
510	            for (int i = 0; i < 4; i++) {
511	                sb.append(String.format("%02X", digest[i]));
512	            }
513	            return sb.toString();
514	        }
515	        catch (NoSuchAlgorithmException e) {
516	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
517	        }
518	    }
519	
