538	    private <T> T findEntityById(Supplier<T> supplier) {
539	        try {
540	            return supplier.get();
541	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
542	            // Just ignore not found exceptions for Jdbc/Jpa realization
543	            return null;
544	        }
545	    }
546	
547	}
